selector_to_html = {"a[href=\"#option-2-external-plugin-package\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Option 2: External plugin package<a class=\"headerlink\" href=\"#option-2-external-plugin-package\" title=\"Link to this heading\">#</a></h4><p>Create a separate package with entry points:</p>", "a[href=\"#add-vendor-backends\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Add vendor backends<a class=\"headerlink\" href=\"#add-vendor-backends\" title=\"Link to this heading\">#</a></h3><p>The dispatch system supports three ways to integrate vendor backends:</p>", "a[href=\"#add-new-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Add new operators<a class=\"headerlink\" href=\"#add-new-operators\" title=\"Link to this heading\">#</a></h2><p>When adding a new operator, modify these files:</p>", "a[href=\"#priority-levels\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Priority levels<a class=\"headerlink\" href=\"#priority-levels\" title=\"Link to this heading\">#</a></h4><p>Use constants from <code class=\"docutils literal notranslate\"><span class=\"pre\">types.py</span></code>:</p>", "a[href=\"#multi-process-safety\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-process safety<a class=\"headerlink\" href=\"#multi-process-safety\" title=\"Link to this heading\">#</a></h2><p>OpManager supports multi-process environments:</p>", "a[href=\"#option-3-environment-based-plugin\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Option 3: Environment-based plugin<a class=\"headerlink\" href=\"#option-3-environment-based-plugin\" title=\"Link to this heading\">#</a></h4><p>The module should provide a <code class=\"docutils literal notranslate\"><span class=\"pre\">register_builtins(registry)</span></code> function.</p>", "a[href=\"#option-1-built-in-vendor-backend\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Option 1: Built-in vendor backend<a class=\"headerlink\" href=\"#option-1-built-in-vendor-backend\" title=\"Link to this heading\">#</a></h4><p>Directory structure:</p>", "a[href=\"#vendor-backend-checklist\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Vendor backend checklist<a class=\"headerlink\" href=\"#vendor-backend-checklist\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#current-vendor-backends\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Current vendor backends<a class=\"headerlink\" href=\"#current-vendor-backends\" title=\"Link to this heading\">#</a></h4><p>The vendor name reported by a backend is what <code class=\"docutils literal notranslate\"><span class=\"pre\">allow_vendors</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">deny_vendors</span></code>, and the <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor:&lt;name&gt;</span></code> tokens match. It is not always the directory name: the MetaX backend is <code class=\"docutils literal notranslate\"><span class=\"pre\">maca</span></code>, the Enflame backend is <code class=\"docutils literal notranslate\"><span class=\"pre\">gcu</span></code>, and the Tsingmicro backend is <code class=\"docutils literal notranslate\"><span class=\"pre\">txda</span></code>.</p><p>See <code class=\"docutils literal notranslate\"><span class=\"pre\">backends/vendor/template/</span></code> for a template to create new vendor backends.</p>", "a[href=\"#test-your-backend\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Test your backend<a class=\"headerlink\" href=\"#test-your-backend\" title=\"Link to this heading\">#</a></h4><p>Enable debug output:</p>", "a[href=\"#add-new-operators-and-vendor-backends\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Add new operators and vendor backends<a class=\"headerlink\" href=\"#add-new-operators-and-vendor-backends\" title=\"Link to this heading\">#</a></h1><h2>Add new operators<a class=\"headerlink\" href=\"#add-new-operators\" title=\"Link to this heading\">#</a></h2><p>When adding a new operator, modify these files:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
